//go:build integration

// Package integration / pipeline_test.go — full-pipeline integration
// tests for migrator-files.
//
// What is and is NOT exercised:
//
//   - REAL Postgres (testcontainers, populated via the harness's
//     Seed* helpers).
//   - REAL Qdrant (testcontainers, seeded via SeedQdrantCollection).
//   - In-memory MOCK Memgraph (legacy.MemgraphMock — the bolt driver
//     is opt-in production code; the same mock is used by every
//     other apply test in this repo).
//   - In-memory MOCK MinIO (legacy.S3Mock — Phase 4 just streams
//     bytes through the ObjectWriter contract; we capture them).
//   - In-process MOCK files-svc (bufconn gRPC server with
//     stub handlers that mint deterministic UUIDs).
//
// Why no real files-svc:
//
//	files-svc itself is testcontainerized (Postgres + Memgraph
//	+ Qdrant + nats) in services/files-svc/tests/integration —
//	end-to-end tests that boot BOTH the migrator AND a files-svc
//	pod live there (or are deferred until sub-PR 9). This file is
//	about migrator-side correctness: per-phase apply, sidecar I/O,
//	rejection-report emission, reconcile-report parity, and status
//	state machine. The bufconn stub gives us deterministic, fast,
//	hermetic feedback.
package integration

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/apply"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/legacy"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/reconcile"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/rejection"
	"github.com/zenithflowinc/omnicore-platform/services/migrator-files/internal/status"
)

// fixtureUserUUID is the resolved new-platform UUID for legacy user 42.
// Plumbed into UploadedByMap so Phase 4 doesn't skip every document
// row with the deferred-resolution rejection note.
const fixtureUserUUID = "11111111-1111-1111-1111-111111111111"

// legacyUserID is the legacy users.id we stamp on every fixture row.
// Mirrors the production pattern — the migrator carries the int around
// until the user-resolution layer maps it to a UUID.
const legacyUserID int64 = 42

// pointer is a tiny generics helper for nullable column fixtures.
func pointer[T any](v T) *T { return &v }

// fixtureSpec captures the cardinalities the task description targets:
// "5 entity types, 3 relationship types, 2 corpora, 4 documents,
// ~20 chunks, ~10 entities, ~6 edges". We hard-code per-entity counts
// here so a future spec change is a single-line edit.
type fixtureSpec struct {
	corpora       int
	docsPerCorpus int
	chunksPerDoc  int

	entityTypes       int
	relationshipTypes int
	entities          int
	edges             int
}

func defaultSpec() fixtureSpec {
	return fixtureSpec{
		corpora:           2,
		docsPerCorpus:     2, // 2 corpora * 2 docs = 4 documents
		chunksPerDoc:      5, // 4 docs * 5 chunks = 20 chunks
		entityTypes:       5,
		relationshipTypes: 3,
		entities:          10,
		edges:             6,
	}
}

// seedFixtures populates legacy Postgres + legacy Qdrant + the
// Memgraph mock with a self-consistent dataset matching `spec`.
// Returns the legacy ids we minted so test bodies can construct
// expected-id maps without re-walking the seed.
type seededIDs struct {
	corpusIDs     []int64
	documentIDs   []int64
	chunkIDs      []int64
	chromaIDs     []string // 1:1 with chunkIDs
	collectionName string
	memgraphEntities []legacy.LegacyEntity
	memgraphEdges    []legacy.LegacyEdge
}

func seedFixtures(ctx context.Context, t *testing.T, h *TestHarness, spec fixtureSpec) seededIDs {
	t.Helper()

	collectionName := h.Cfg.VectorCollection
	out := seededIDs{collectionName: collectionName}

	// 1) Corpora.
	for i := 0; i < spec.corpora; i++ {
		ownerID := legacyUserID
		cid := h.SeedCorpus(ctx,
			fmt.Sprintf("Corpus %d", i+1),
			"private",
			collectionName,
			&ownerID,
		)
		out.corpusIDs = append(out.corpusIDs, cid)
	}

	// 2) Documents and 3) chunks. We iterate corpus-major so the
	// chunk_index sequences stay tight per document.
	chromaCounter := 0
	for _, cid := range out.corpusIDs {
		for d := 0; d < spec.docsPerCorpus; d++ {
			path := fmt.Sprintf("legacy-doc-%d-%d.txt", cid, d)
			body := []byte(fmt.Sprintf("hello from doc %d/%d body bytes", cid, d))
			uploader := legacyUserID
			docID := h.SeedDocument(ctx, cid, path, path, "txt", &uploader, body)
			out.documentIDs = append(out.documentIDs, docID)

			for c := 0; c < spec.chunksPerDoc; c++ {
				// Stable, version-5 deterministic UUIDs make
				// re-runs predictable — no clock-time noise in
				// the fixtures.
				chromaID := deterministicUUID(fmt.Sprintf("legacy:chunk-vec:%d:%d", docID, c))
				start := int32(c * 100)
				end := int32(c*100 + 99)
				cidLegacy := h.SeedChunk(ctx, docID, int32(c),
					fmt.Sprintf("chunk %d of doc %d", c, docID),
					chromaID,
					"all-mpnet-base-v2",
					&start, &end,
				)
				out.chunkIDs = append(out.chunkIDs, cidLegacy)
				out.chromaIDs = append(out.chromaIDs, chromaID)
				chromaCounter++
			}
		}
	}

	// 4) Qdrant — seed one point per chunk with a small dim-N vector
	// derived from the index (pristine values so we can verify Phase
	// 6 copied them verbatim).
	pts := make([]QdrantSeedPoint, 0, len(out.chromaIDs))
	for i, id := range out.chromaIDs {
		vec := make([]float32, h.Cfg.VectorDim)
		for d := range vec {
			vec[d] = float32(i+1) * float32(d+1) * 0.01
		}
		pts = append(pts, QdrantSeedPoint{ID: id, Vector: vec})
	}
	h.SeedQdrantCollection(ctx, pts)

	// 5) Memgraph mock — entity types, relationship types, entities,
	// edges. Phase 9 (provenance) is deliberately empty per the
	// legacy gap.
	for i := 0; i < spec.entityTypes; i++ {
		name := fmt.Sprintf("TYPE_%d", i+1)
		h.Memgraph.EntityTypes = append(h.Memgraph.EntityTypes, legacy.EntityType{
			Name:     name,
			LegacyID: fmt.Sprintf("legacy:entity-type:%d:%s", h.Cfg.LegacyOrgID, name),
		})
	}
	for i := 0; i < spec.relationshipTypes; i++ {
		name := fmt.Sprintf("REL_%d", i+1)
		h.Memgraph.RelationshipTypes = append(h.Memgraph.RelationshipTypes, legacy.RelationshipType{
			Name:       name,
			IsDirected: true,
			LegacyID:   fmt.Sprintf("legacy:rel-type:%d:%s", h.Cfg.LegacyOrgID, name),
		})
	}
	for i := 0; i < spec.entities; i++ {
		typeName := h.Memgraph.EntityTypes[i%len(h.Memgraph.EntityTypes)].Name
		ent := legacy.LegacyEntity{
			LegacyID:  fmt.Sprintf("legacy:entity:%d", i+1),
			Label:     fmt.Sprintf("Entity %d", i+1),
			TypeName:  typeName,
			CreatedAt: time.Unix(0, 0).UTC(),
		}
		h.Memgraph.Entities = append(h.Memgraph.Entities, ent)
		out.memgraphEntities = append(out.memgraphEntities, ent)
	}
	for i := 0; i < spec.edges; i++ {
		// Wire edges between entity i and entity i+1 (mod count) so
		// every edge has both endpoints resolvable from the entity
		// map. RelType cycles through the 3 seeded types.
		src := h.Memgraph.Entities[i%len(h.Memgraph.Entities)]
		tgt := h.Memgraph.Entities[(i+1)%len(h.Memgraph.Entities)]
		relType := h.Memgraph.RelationshipTypes[i%len(h.Memgraph.RelationshipTypes)].Name
		ed := legacy.LegacyEdge{
			LegacyID:         fmt.Sprintf("legacy:edge:%d", i+1),
			SourceLegacyID:   src.LegacyID,
			TargetLegacyID:   tgt.LegacyID,
			RelationshipType: relType,
			CreatedAt:        time.Unix(0, 0).UTC(),
		}
		h.Memgraph.Edges = append(h.Memgraph.Edges, ed)
		out.memgraphEdges = append(out.memgraphEdges, ed)
	}

	return out
}

// runFullPipeline drives every phase in order and returns the
// per-phase outputs + sidecar maps. Tests that need different
// scenarios (empty org, idempotent re-run) compose this differently.
type pipelineOutputs struct {
	entityTypes       *apply.EntityTypesResult
	relationshipTypes *apply.RelationshipTypesResult
	corpora           apply.CorporaApplyOutput
	documents         apply.DocumentsApplyOutput
	chunks            apply.ChunksApplyOutput
	embeddings        apply.EmbeddingsApplyOutput
	entities          apply.EntitiesApplyOutput
	edges             apply.EdgesApplyOutput
	provenance        apply.ProvenanceApplyOutput
}

func runFullPipeline(ctx context.Context, t *testing.T, h *TestHarness, w rejection.Writer) pipelineOutputs {
	t.Helper()
	var out pipelineOutputs
	var err error

	// Phase 1.
	out.entityTypes, err = apply.EntityTypesApply(ctx, apply.EntityTypesArgs{
		Memgraph:    h.Memgraph,
		Client:      h.ETClient,
		LegacyOrgID: int(h.Cfg.LegacyOrgID),
		NewOrgID:    h.Cfg.NewOrgID,
	})
	require.NoError(t, err, "phase 1: entity-types")
	writeIDMap(t, h.RunDir, "entity_type_map.json", out.entityTypes.IDByLegacyID)

	// Phase 2.
	out.relationshipTypes, err = apply.RelationshipTypesApply(ctx, apply.RelationshipTypesArgs{
		Memgraph:    h.Memgraph,
		Client:      h.RTClient,
		LegacyOrgID: int(h.Cfg.LegacyOrgID),
		NewOrgID:    h.Cfg.NewOrgID,
	})
	require.NoError(t, err, "phase 2: relationship-types")
	writeIDMap(t, h.RunDir, "relationship_type_map.json", out.relationshipTypes.IDByLegacyID)

	// Phase 3.
	out.corpora, err = apply.CorporaApply(ctx, apply.CorporaApplyInput{
		Reader:      h.PG,
		Client:      h.CorpusClient,
		LegacyOrgID: h.Cfg.LegacyOrgID,
		Writer:      w,
	})
	require.NoError(t, err, "phase 3: corpora")
	writeIDMap(t, h.RunDir, "corpus_map.json", out.corpora.LegacyIDMap)

	// Phase 4.
	out.documents, err = apply.DocumentsApply(ctx, apply.DocumentsApplyInput{
		Reader:            h.PG,
		FS:                h.LegacyDocs,
		Object:            h.S3,
		Client:            h.DocClient,
		LegacyOrgID:       h.Cfg.LegacyOrgID,
		OrgID:             h.Cfg.NewOrgID,
		Bucket:            "files-test",
		CorpusLegacyIDMap: out.corpora.LegacyIDMap,
		UploadedByMap:     map[int64]string{legacyUserID: fixtureUserUUID},
		Writer:            w,
	})
	require.NoError(t, err, "phase 4: documents")
	writeIDMap(t, h.RunDir, "document_map.json", out.documents.LegacyIDMap)

	// Phase 5.
	out.chunks, err = apply.ChunksApply(ctx, apply.ChunksApplyInput{
		Reader:              h.PG,
		Client:              h.DocClient,
		DocumentLegacyIDMap: out.documents.LegacyIDMap,
		LegacyOrgID:         h.Cfg.LegacyOrgID,
		Writer:              w,
	})
	require.NoError(t, err, "phase 5: chunks")
	writeIDMap(t, h.RunDir, "chunk_map.json", out.chunks.LegacyIDMap)

	// Phase 6.
	out.embeddings, err = apply.EmbeddingsApply(ctx, apply.EmbeddingsApplyInput{
		PG:                  h.PG,
		Qdrant:              h.Qdrant,
		Client:              h.DocClient,
		DocumentLegacyIDMap: out.documents.LegacyIDMap,
		LegacyOrgID:         h.Cfg.LegacyOrgID,
		Writer:              w,
	})
	require.NoError(t, err, "phase 6: embeddings")

	// Phase 7. Requires a non-empty TypeIDMap by contract; if Phase 1
	// returned no rows, downstream phases would fail input validation
	// — that's expected on an empty-org run, so we skip them and
	// leave the zero-valued outputs (the empty-org test asserts the
	// zeros directly).
	if len(out.entityTypes.IDByLegacyID) == 0 {
		writeIDMap(t, h.RunDir, "entity_map.json", map[string]string{})
		writeIDMap(t, h.RunDir, "edge_map.json", map[string]string{})
		out.entities.LegacyIDMap = map[string]string{}
		out.edges.LegacyIDMap = map[string]string{}
		return out
	}
	out.entities, err = apply.EntitiesApply(ctx, apply.EntitiesApplyInput{
		Reader:      h.Memgraph,
		Client:      h.EntityClient,
		LegacyOrgID: int(h.Cfg.LegacyOrgID),
		TypeIDMap:   out.entityTypes.IDByLegacyID,
		CorpusIDMap: out.corpora.LegacyIDMap,
		Writer:      w,
	})
	require.NoError(t, err, "phase 7: entities")
	writeIDMap(t, h.RunDir, "entity_map.json", out.entities.LegacyIDMap)

	// Phase 8. Same input-validation contract — skip on empty maps.
	if len(out.entities.LegacyIDMap) == 0 || len(out.relationshipTypes.IDByLegacyID) == 0 {
		writeIDMap(t, h.RunDir, "edge_map.json", map[string]string{})
		out.edges.LegacyIDMap = map[string]string{}
		return out
	}
	out.edges, err = apply.EdgesApply(ctx, apply.EdgesApplyInput{
		Reader:                h.Memgraph,
		Client:                h.EdgeClient,
		LegacyOrgID:           int(h.Cfg.LegacyOrgID),
		EntityIDMap:           out.entities.LegacyIDMap,
		RelationshipTypeIDMap: out.relationshipTypes.IDByLegacyID,
		Writer:                w,
	})
	require.NoError(t, err, "phase 8: edges")
	writeIDMap(t, h.RunDir, "edge_map.json", out.edges.LegacyIDMap)

	// Phase 9. Provenance is the terminal phase — no sidecar.
	// Requires entity_map, edge_map, AND chunk_map all non-empty.
	if len(out.entities.LegacyIDMap) == 0 || len(out.edges.LegacyIDMap) == 0 || len(out.chunks.LegacyIDMap) == 0 {
		return out
	}
	out.provenance, err = apply.ProvenanceApply(ctx, apply.ProvenanceApplyInput{
		Reader:       h.Memgraph,
		EntityClient: h.EntityClient,
		EdgeClient:   h.EdgeClient,
		LegacyOrgID:  int(h.Cfg.LegacyOrgID),
		EntityIDMap:  out.entities.LegacyIDMap,
		EdgeIDMap:    out.edges.LegacyIDMap,
		ChunkIDMap:   out.chunks.LegacyIDMap,
		Writer:       w,
	})
	require.NoError(t, err, "phase 9: provenance")
	return out
}

// writeIDMap mirrors cmd/server's writeIDMap but is duplicated here
// (kept intentionally tiny) so the test package doesn't import
// cmd/server. Rejection notes about not having a sidecar bypass would
// be a misleading distraction in test output.
func writeIDMap(t *testing.T, runDir, filename string, m map[string]string) {
	t.Helper()
	require.NoError(t, os.MkdirAll(runDir, 0o750))
	body, err := json.MarshalIndent(m, "", "  ")
	require.NoError(t, err)
	require.NoError(t, os.WriteFile(filepath.Join(runDir, filename), body, 0o600))
}

// readJSONL reads every line of an NDJSON file into a slice of
// rejection.Note. Empty file yields an empty slice (not an error).
func readJSONL(t *testing.T, path string) []rejection.Note {
	t.Helper()
	body, err := os.ReadFile(path) //nolint:gosec // test fixture
	require.NoError(t, err, "read %s", path)
	var notes []rejection.Note
	for _, line := range strings.Split(strings.TrimSpace(string(body)), "\n") {
		if line == "" {
			continue
		}
		var n rejection.Note
		require.NoError(t, json.Unmarshal([]byte(line), &n), "decode line %q", line)
		notes = append(notes, n)
	}
	return notes
}

// requireSomeNoteContains asserts that at least one note's Reason
// contains the substring `needle`, with a clear failure message
// listing every note observed when no match is found.
func requireSomeNoteContains(t *testing.T, notes []rejection.Note, needle string) {
	t.Helper()
	for _, n := range notes {
		if strings.Contains(n.Reason, needle) {
			return
		}
	}
	reasons := make([]string, 0, len(notes))
	for _, n := range notes {
		reasons = append(reasons, fmt.Sprintf("[%s/%s] %s", n.Phase, n.Severity, n.Reason))
	}
	t.Fatalf("expected a rejection note containing %q; got %d notes:\n  %s",
		needle, len(notes), strings.Join(reasons, "\n  "))
}

// ----------------------------------------------------------------------
// Tests
// ----------------------------------------------------------------------

// TestPipelineFullRun is the end-to-end happy-path test. Drives every
// phase, asserts cardinalities, and runs reconcile + status.
func TestPipelineFullRun(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping integration test in short mode")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	h := NewTestHarness(t, HarnessConfig{})
	spec := defaultSpec()
	seeded := seedFixtures(ctx, t, h, spec)

	// Open a real rejection writer so we can assert on the JSONL file.
	rejW, err := rejection.NewFileWriter(h.RejectionDir)
	require.NoError(t, err)
	defer rejW.Close() //nolint:errcheck

	out := runFullPipeline(ctx, t, h, rejW)
	require.NoError(t, rejW.Close())

	// 1. Per-phase cardinality.
	require.Equal(t, spec.entityTypes, out.entityTypes.Bootstrapped, "entity-types bootstrapped")
	require.Equal(t, spec.relationshipTypes, out.relationshipTypes.Bootstrapped, "relationship-types bootstrapped")
	require.Equal(t, spec.corpora, out.corpora.Read)
	require.Equal(t, spec.corpora, out.corpora.Created+out.corpora.AlreadyMigrated)

	expectedDocs := spec.corpora * spec.docsPerCorpus
	require.Equal(t, expectedDocs, out.documents.Read, "documents read")
	require.Equal(t, expectedDocs, out.documents.Uploaded+out.documents.AlreadyMigrated, "documents uploaded")

	expectedChunks := expectedDocs * spec.chunksPerDoc
	require.Equal(t, expectedChunks, out.chunks.ChunksRead, "chunks read")
	require.Equal(t, expectedChunks, out.chunks.ChunksMigrated, "chunks migrated")

	require.Equal(t, expectedChunks, out.embeddings.ChunksRead, "embeddings refs read")
	require.Equal(t, expectedChunks, out.embeddings.PointsFetched, "qdrant points fetched")
	require.Equal(t, expectedChunks, out.embeddings.EmbeddingsWritten, "embeddings written")

	require.Equal(t, spec.entities, out.entities.Migrated, "entities migrated")
	require.Equal(t, spec.edges, out.edges.Migrated, "edges migrated")

	// Provenance: legacy returns 0 by design — both Read totals zero,
	// and the apply layer should have emitted a deferred-provenance
	// note per side.
	require.Zero(t, out.provenance.EntityLinksRead)
	require.Zero(t, out.provenance.EdgeLinksRead)

	// 2. Stub-side counts mirror the apply-side counts (sanity that
	// every apply call hit the wire).
	require.Equal(t, len(seeded.documentIDs), h.FilesStub.MigrateUploadCalls)
	require.Equal(t, len(seeded.documentIDs), h.FilesStub.MigrateChunksCalls)
	require.Equal(t, len(seeded.documentIDs), h.FilesStub.MigrateChunkEmbeddingsCalls)
	require.Equal(t, spec.entities, h.FilesStub.MigrateEntityCalls)
	require.Equal(t, spec.edges, h.FilesStub.MigrateEdgeCalls)

	// Provenance never emits links (legacy gap), so no MigrateProvenance
	// RPC is issued by the apply layer.
	require.Equal(t, 0, h.FilesStub.MigrateEntityProvenanceCalls)
	require.Equal(t, 0, h.FilesStub.MigrateEdgeProvenanceCalls)

	// 3. Sidecars exist and have the right cardinality.
	for _, tc := range []struct {
		file string
		want int
	}{
		{"entity_type_map.json", spec.entityTypes},
		{"relationship_type_map.json", spec.relationshipTypes},
		{"corpus_map.json", spec.corpora},
		{"document_map.json", expectedDocs},
		{"chunk_map.json", expectedChunks},
		{"entity_map.json", spec.entities},
		{"edge_map.json", spec.edges},
	} {
		path := filepath.Join(h.RunDir, tc.file)
		require.FileExists(t, path, tc.file)
		body, err := os.ReadFile(path) //nolint:gosec // test fixture
		require.NoError(t, err)
		var m map[string]string
		require.NoError(t, json.Unmarshal(body, &m), "decode %s", tc.file)
		require.Equal(t, tc.want, len(m), "%s entry count", tc.file)
	}

	// 4. Rejection report — provenance gap notes are guaranteed by
	// design; everything else should be silent on the happy path.
	notes := readJSONL(t, filepath.Join(h.RejectionDir, "rejections.jsonl"))
	require.NotEmpty(t, notes, "rejection report should contain at least the provenance gap notes")
	requireSomeNoteContains(t, notes, "no entity↔chunk provenance")
	requireSomeNoteContains(t, notes, "no edge↔chunk provenance")

	// 5. S3 mock recorded one Put per document.
	require.Len(t, h.S3.Puts, expectedDocs, "minio puts")
	for _, p := range h.S3.Puts {
		require.Equal(t, "files-test", p.Bucket)
		require.Greater(t, len(p.Body), 0)
	}

	// 6. Embeddings round-tripped the legacy vector verbatim.
	for _, legacyChunkID := range seeded.chunkIDs {
		key := fmt.Sprintf("legacy:chunk:%d", legacyChunkID)
		v, ok := h.FilesStub.Embeddings[key]
		require.True(t, ok, "embedding missing for %s", key)
		require.Equal(t, int(h.Cfg.VectorDim), len(v), "embedding dim for %s", key)
	}

	// 7. Reconcile — count parity for every phase, zero mismatches.
	report, err := reconcile.Reconcile(ctx, reconcile.Input{
		LegacyMemgraph: h.Memgraph,
		LegacyCorpus:   h.PG,
		LegacyDocument: h.PG,
		LegacyChunks:   h.PG,
		Clients: reconcile.Clients{
			EntityType:       h.ETClient,
			RelationshipType: h.RTClient,
			Corpus:           h.CorpusClient,
			Document:         h.DocClient,
			Entity:           h.EntityClient,
			Edge:             h.EdgeClient,
		},
		Sidecars: reconcile.Sidecars{
			EntityType:       out.entityTypes.IDByLegacyID,
			RelationshipType: out.relationshipTypes.IDByLegacyID,
			Corpus:           out.corpora.LegacyIDMap,
			Document:         out.documents.LegacyIDMap,
			Chunk:            out.chunks.LegacyIDMap,
			Entity:           out.entities.LegacyIDMap,
			Edge:             out.edges.LegacyIDMap,
		},
		LegacyOrgID: int(h.Cfg.LegacyOrgID),
		OrgID:       h.Cfg.NewOrgID,
		SampleSize:  reconcile.DefaultSampleSize,
	})
	require.NoError(t, err)
	// Embeddings is excluded from the parity assertion by reconcile
	// design: it has no sidecar (Phase 6 writes directly to new
	// Qdrant via files-svc, no migrator-side ledger), so when
	// legacy_count > 0 reconcile reports parity_ok=false and emits a
	// "consult Phase 6 apply RESULT" note. Operators are expected to
	// cross-check the apply RESULT.embeddings_written against
	// legacy_count manually — we assert that here.
	for _, name := range []string{"entity-types", "relationship-types", "corpora", "documents", "chunks", "entities", "edges", "provenance"} {
		pr := report.Phases[name]
		require.NotNil(t, pr, "phase %s missing from report", name)
		require.True(t, pr.CountParityOK, "phase %s parity: legacy=%d new=%d sidecar=%d notes=%v",
			name, pr.LegacyCount, pr.NewCount, pr.SidecarCount, pr.Notes)
		require.Zero(t, pr.SampleMismatches, "phase %s sample mismatches: %v", name, pr.Notes)
	}
	embed := report.Phases["embeddings"]
	require.NotNil(t, embed)
	require.False(t, embed.CountParityOK, "embeddings has no sidecar by design — parity_ok must be false when legacy>0")
	// And the apply-side counter agrees with legacy count.
	require.Equal(t, embed.LegacyCount, out.embeddings.EmbeddingsWritten,
		"phase 6 RESULT.embeddings_written must match legacy count")

	// 8. Status — every phase is in a known state.
	rep, err := status.Summarize(ctx, status.Input{
		OrgID:  h.Cfg.NewOrgID,
		RunDir: h.RunDir,
		Bucket: "migrator-cursor",
		Cursor: nil, // Status falls back to sidecar-only.
	})
	require.NoError(t, err)
	require.Len(t, rep.Phases, 9)
	for _, row := range rep.Phases {
		switch row.State {
		case status.StateMigrated, status.StateNoSidecar, status.StateMigratedNoCursor, status.StateEmpty:
			// acceptable terminal states
		default:
			t.Fatalf("phase %s unexpected state %q", row.Phase, row.State)
		}
	}
}

// TestPipelineEmptyOrg verifies the migrator behaves cleanly when the
// legacy org has no rows. Every phase produces 0 rows, sidecars are
// either absent or empty maps, and reconcile returns 0 mismatches.
func TestPipelineEmptyOrg(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping integration test in short mode")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	h := NewTestHarness(t, HarnessConfig{})

	// Even an empty org must have the Qdrant collection created
	// (Phase 6 reads it for legacy refs — empty refs are fine).
	h.SeedQdrantCollection(ctx, nil)

	rejW, err := rejection.NewFileWriter(h.RejectionDir)
	require.NoError(t, err)
	defer rejW.Close() //nolint:errcheck

	out := runFullPipeline(ctx, t, h, rejW)
	require.NoError(t, rejW.Close())

	require.Zero(t, out.entityTypes.Bootstrapped)
	require.Zero(t, out.relationshipTypes.Bootstrapped)
	require.Zero(t, out.corpora.Read)
	require.Zero(t, out.documents.Read)
	require.Zero(t, out.chunks.ChunksRead)
	require.Zero(t, out.embeddings.ChunksRead)
	require.Zero(t, out.entities.Migrated)
	require.Zero(t, out.edges.Migrated)
	require.Zero(t, out.provenance.EntityLinksMigrated)
	require.Zero(t, out.provenance.EdgeLinksMigrated)

	// Phases 1+2 short-circuit before issuing the RPC when there are
	// no rows; the rest still issue (with empty inputs) only when the
	// corresponding sidecar map is populated. Either way, no errors.
	require.Equal(t, 0, h.FilesStub.BootstrapEntityTypesCalls)
	require.Equal(t, 0, h.FilesStub.BootstrapRelationshipTypesCalls)
	require.Equal(t, 0, h.FilesStub.MigrateCorpusCalls)
	require.Equal(t, 0, h.FilesStub.MigrateUploadCalls)
	require.Equal(t, 0, h.FilesStub.MigrateChunksCalls)
	require.Equal(t, 0, h.FilesStub.MigrateEntityCalls)
	require.Equal(t, 0, h.FilesStub.MigrateEdgeCalls)

	// Reconcile — vacuously parity-OK across every phase.
	report, err := reconcile.Reconcile(ctx, reconcile.Input{
		LegacyMemgraph: h.Memgraph,
		LegacyCorpus:   h.PG,
		LegacyDocument: h.PG,
		LegacyChunks:   h.PG,
		Clients: reconcile.Clients{
			EntityType: h.ETClient, RelationshipType: h.RTClient,
			Corpus: h.CorpusClient, Document: h.DocClient,
			Entity: h.EntityClient, Edge: h.EdgeClient,
		},
		Sidecars: reconcile.Sidecars{
			EntityType:       out.entityTypes.IDByLegacyID,
			RelationshipType: out.relationshipTypes.IDByLegacyID,
			Corpus:           out.corpora.LegacyIDMap,
			Document:         out.documents.LegacyIDMap,
			Chunk:            out.chunks.LegacyIDMap,
			Entity:           out.entities.LegacyIDMap,
			Edge:             out.edges.LegacyIDMap,
		},
		LegacyOrgID: int(h.Cfg.LegacyOrgID),
		OrgID:       h.Cfg.NewOrgID,
	})
	require.NoError(t, err)
	require.Zero(t, report.Mismatches)
}

// TestPipelineRerunIdempotent runs the full pipeline twice. The
// second pass should report AlreadyMigrated > 0 for the corpus and
// document phases (the only two whose proto response surfaces
// already_migrated) and produce identical sidecar contents.
func TestPipelineRerunIdempotent(t *testing.T) {
	if testing.Short() {
		t.Skip("skipping integration test in short mode")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
	defer cancel()

	h := NewTestHarness(t, HarnessConfig{})
	spec := defaultSpec()
	_ = seedFixtures(ctx, t, h, spec)

	rejW, err := rejection.NewFileWriter(h.RejectionDir)
	require.NoError(t, err)
	defer rejW.Close() //nolint:errcheck

	first := runFullPipeline(ctx, t, h, rejW)

	// Snapshot every sidecar before the second pass so we can prove
	// the second pass didn't shuffle ids.
	snap := snapshotSidecars(t, h.RunDir)

	second := runFullPipeline(ctx, t, h, rejW)
	require.NoError(t, rejW.Close())

	// AlreadyMigrated > 0 on the phases whose proto surfaces it.
	require.Equal(t, spec.corpora, second.corpora.AlreadyMigrated, "corpora rerun should be idempotent")
	require.Equal(t, spec.corpora*spec.docsPerCorpus, second.documents.AlreadyMigrated, "documents rerun should be idempotent")

	// Phases without `already_migrated` in their response shape
	// (entities, edges, chunks) still re-issue the RPC; the stub
	// returns the existing row so counts stay equal across runs.
	require.Equal(t, first.entities.Migrated, second.entities.Migrated)
	require.Equal(t, first.edges.Migrated, second.edges.Migrated)
	require.Equal(t, first.chunks.ChunksMigrated, second.chunks.ChunksMigrated)

	// Sidecars are unchanged byte-for-byte (deterministic UUIDs).
	after := snapshotSidecars(t, h.RunDir)
	for k, v := range snap {
		require.Equal(t, v, after[k], "sidecar %s drifted between runs", k)
	}
}

// snapshotSidecars reads every JSON file in runDir and returns a
// filename → decoded-map index. Used by the rerun test to assert
// stability across passes.
func snapshotSidecars(t *testing.T, runDir string) map[string]map[string]string {
	t.Helper()
	entries, err := os.ReadDir(runDir)
	require.NoError(t, err)
	out := map[string]map[string]string{}
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".json") {
			continue
		}
		body, err := os.ReadFile(filepath.Join(runDir, e.Name())) //nolint:gosec // test fixture
		require.NoError(t, err)
		var m map[string]string
		require.NoError(t, json.Unmarshal(body, &m))
		out[e.Name()] = m
	}
	return out
}

