// gRPC API is stable within this major; bumping requires re-vetting
// the qdrant-go client wire-compat surface (the legacy-Qdrant in
// production is also a v1.x). Pin to v1.13.x because the qdrant-go
// v1.17.1 client we depend on needs a server new enough to understand
// the Dense-oneof Vector wire format.
const QdrantImage = "qdrant/qdrant:v1.13.0"

// bufconnBufferSize is the in-memory listener buffer for the bufconn
// gRPC server. 1 MiB is more than enough for the small messages the
// migrator emits — this isn't a throughput test.
const bufconnBufferSize = 1024 * 1024

// HarnessConfig tweaks the boot-up behavior. Tests that don't care
// about specific knobs can pass a zero value.
type HarnessConfig struct {
	// LegacyOrgID seeded into the legacy postgres rows. Default 1.
	LegacyOrgID int64
	// NewOrgID is the new-platform org UUID. Default a stable
	// "00000000-0000-0000-0000-0000000000aa" so tests have a
	// human-recognizable id in failure output.
	NewOrgID string
	// VectorCollection is the legacy Qdrant collection name seeded
	// with the chunk fixtures. Default "legacy_test_collection".
	VectorCollection string
	// VectorDim is the dimension of the seeded vectors. Default 4 —
	// the migrator copies bytes verbatim, so a small dim keeps the
	// test fixtures cheap.
	VectorDim uint64
}

// TestHarness wires Postgres + Qdrant + in-process gRPC + Memgraph
// mock + S3 mock together for full-pipeline tests.
type TestHarness struct {
	t *testing.T

	// Containers + connections.
	pgPool   *pgxpool.Pool
	pgDSN    string
	pgClean  func()
	qdrantC  testcontainers.Container
	qdrantHost string
	qdrantPort int

	// Production reader instances pointed at the testcontainers.
	PG     *legacy.PostgresReader
	Qdrant *legacy.QdrantClient

	// Mocks for the data sources we don't containerize.
	Memgraph *legacy.MemgraphMock
	S3       *legacy.S3Mock

	// In-process gRPC server + clients.
	GRPC          *grpc.Server
	GRPCConn      *grpc.ClientConn
	FilesStub *FilesStub
	ETClient      entitytypev1.EntityTypeServiceClient
	RTClient      relationshiptypev1.RelationshipTypeServiceClient
	CorpusClient  corpusv1.CorpusServiceClient
	DocClient     documentv1.DocumentServiceClient
	EntityClient  entityv1.EntityServiceClient
	EdgeClient    edgev1.EdgeServiceClient

	// Filesystem state owned by the harness.
	RunDir       string
	RejectionDir string
	LegacyDocs   *legacy.FilesystemMock // legacy file_path → bytes

	// Configuration (echoed for tests).
	Cfg HarnessConfig
}

// NewTestHarness boots Postgres + Qdrant, applies the schema, runs no
// fixture seeding (use Seed* helpers), and returns a fully wired
// harness. Cleanup is registered with t.Cleanup — tests don't need to
// defer h.Cleanup() but may.
//
// Each container is gated by t.Skip when Docker is unreachable so
// developers without a daemon get a clean signal rather than a
// timeout.
func NewTestHarness(t *testing.T, cfg HarnessConfig) *TestHarness {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()

	if cfg.LegacyOrgID == 0 {
		cfg.LegacyOrgID = 1
	}
	if cfg.NewOrgID == "" {
		cfg.NewOrgID = "00000000-0000-0000-0000-0000000000aa"
	}
	if cfg.VectorCollection == "" {
		cfg.VectorCollection = "legacy_test_collection"
	}
	if cfg.VectorDim == 0 {
		cfg.VectorDim = 4
	}

	h := &TestHarness{t: t, Cfg: cfg}

	// 1. Postgres — reuse helpers.go's StartLegacyPostgres for the
	// container + base DDL, then layer the fuller fixture schema
	// on top. The base DDL only covers entity_types/relationship_types
	// (Phases 1+2) — the fuller schema adds document_collections /
	// documents / document_chunks (Phases 3-6).
	pool, dsn, pgClean := StartLegacyPostgres(t)
	h.pgPool = pool
	h.pgDSN = dsn
	h.pgClean = pgClean
	require.NoError(t, applyLegacySchemaFile(ctx, pool))

	pgReader, err := legacy.NewPostgresReader(ctx, dsn)
	require.NoError(t, err, "open legacy postgres reader")
	h.PG = pgReader

	// 2. Qdrant.
	h.startQdrant(ctx)
	qURL := fmt.Sprintf("%s:%d", h.qdrantHost, h.qdrantPort)
	qClient, err := legacy.NewQdrantReader(ctx, qURL)
	require.NoError(t, err, "open legacy qdrant reader")
	h.Qdrant = qClient

	// 3. Mocks for the data sources we don't containerize.
	h.Memgraph = &legacy.MemgraphMock{}
	h.S3 = &legacy.S3Mock{}
	h.LegacyDocs = &legacy.FilesystemMock{Files: map[string][]byte{}}

	// 4. Bufconn in-process gRPC server with stub services.
	h.startBufconnGRPC(ctx)

	// 5. Tmpdirs.
	h.RunDir = t.TempDir()
	h.RejectionDir = t.TempDir()

	t.Cleanup(h.Cleanup)
	return h
}

// Cleanup terminates containers, closes connections, and is safe to
// call multiple times. Registered with t.Cleanup automatically.
func (h *TestHarness) Cleanup() {
	if h == nil {
		return
	}
	if h.GRPCConn != nil {
		_ = h.GRPCConn.Close()
		h.GRPCConn = nil
	}
	if h.GRPC != nil {
		h.GRPC.Stop()
		h.GRPC = nil
	}
	if h.Qdrant != nil {
		_ = h.Qdrant.Close()
		h.Qdrant = nil
	}
	if h.qdrantC != nil {
		_ = h.qdrantC.Terminate(context.Background())
		h.qdrantC = nil
	}
	if h.PG != nil {
		h.PG.Close()
		h.PG = nil
	}
	if h.pgClean != nil {
		h.pgClean()
		h.pgClean = nil
	}
}

// startQdrant brings up qdrant/qdrant on a generic container with the
// gRPC port (6334) exposed and waits until the HTTP readiness endpoint
// returns 200.
func (h *TestHarness) startQdrant(ctx context.Context) {
	h.t.Helper()
	req := testcontainers.ContainerRequest{
		Image:        QdrantImage,
		ExposedPorts: []string{"6333/tcp", "6334/tcp"},
		WaitingFor: wait.ForAll(
			wait.ForListeningPort("6334/tcp").WithStartupTimeout(60*time.Second),
			wait.ForHTTP("/readyz").WithPort("6333/tcp").WithStartupTimeout(60*time.Second),
		),
	}
	c, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: req,
		Started:          true,
	})
	require.NoError(h.t, err, "start qdrant container")
	host, err := c.Host(ctx)
	require.NoError(h.t, err)
	port, err := c.MappedPort(ctx, "6334/tcp")
	require.NoError(h.t, err)
	h.qdrantC = c
	h.qdrantHost = host
	h.qdrantPort = int(port.Num())
}

// applyLegacySchemaFile runs fixtures/legacy_schema.sql against the
// already-running Postgres pool. Reads the SQL from disk so reviewers
// see one canonical definition (rather than duplicating it in a Go
// const).
func applyLegacySchemaFile(ctx context.Context, pool *pgxpool.Pool) error {
	path := filepath.Join("fixtures", "legacy_schema.sql")
	body, err := os.ReadFile(path) //nolint:gosec // operator-controlled fixture
	if err != nil {
		return fmt.Errorf("read %s: %w", path, err)
	}
	if _, err := pool.Exec(ctx, string(body)); err != nil {
		return fmt.Errorf("apply %s: %w", path, err)
	}
	return nil
}

// QdrantSeedPoint is one fixture point seeded into the legacy Qdrant
// before a pipeline test runs. The harness wires the collection,
// dimension, and content; tests provide ID + vector.
type QdrantSeedPoint struct {
	ID     string    // UUID string (chroma_id)
	Vector []float32 // length must == cfg.VectorDim
}

// SeedQdrantCollection (re)creates the configured legacy collection
// and upserts the supplied points. Safe to call multiple times — each
// call deletes and recreates the collection.
func (h *TestHarness) SeedQdrantCollection(ctx context.Context, points []QdrantSeedPoint) {
	h.t.Helper()
	// Open a separate qdrant-go client just for seeding — the
	// production legacy.QdrantClient is read-only by contract.
	cfg := &qdrant.Config{
		Host:                   h.qdrantHost,
		Port:                   h.qdrantPort,
		SkipCompatibilityCheck: true,
	}
	c, err := qdrant.NewClient(cfg)
	require.NoError(h.t, err, "open seeding qdrant client")
	defer func() { _ = c.Close() }()

	// Delete-if-exists then create. Qdrant returns OK on
	// delete-of-missing.
	_ = c.DeleteCollection(ctx, h.Cfg.VectorCollection)

	require.NoError(h.t, c.CreateCollection(ctx, &qdrant.CreateCollection{
		CollectionName: h.Cfg.VectorCollection,
		VectorsConfig: qdrant.NewVectorsConfig(&qdrant.VectorParams{
			Size:     h.Cfg.VectorDim,
			Distance: qdrant.Distance_Cosine,
		}),
	}), "create qdrant collection")

	if len(points) == 0 {
		return
	}

	pts := make([]*qdrant.PointStruct, 0, len(points))
	for _, p := range points {
		require.Equal(h.t, int(h.Cfg.VectorDim), len(p.Vector),
			"seed vector dim mismatch for point %s", p.ID)
		pts = append(pts, &qdrant.PointStruct{
			Id:      qdrant.NewIDUUID(p.ID),
			Vectors: qdrant.NewVectorsDense(p.Vector),
		})
	}
	wait := true
	_, err = c.Upsert(ctx, &qdrant.UpsertPoints{
		CollectionName: h.Cfg.VectorCollection,
		Wait:           &wait,
		Points:         pts,
	})
	require.NoError(h.t, err, "upsert qdrant points")
}

// startBufconnGRPC creates an in-process bufconn server, registers
// the stub services, and dials a client connection that the migrator
// uses through the apply-layer gRPC interfaces. The stub state lives
// in h.FilesStub so tests can assert on call counts / ids.
func (h *TestHarness) startBufconnGRPC(ctx context.Context) {
	h.t.Helper()
	lis := bufconn.Listen(bufconnBufferSize)
	srv := grpc.NewServer()
	stub := newFilesStub()
	registerFilesStub(srv, stub)

	go func() {
		_ = srv.Serve(lis)
	}()

	conn, err := grpc.DialContext(ctx, "bufconn", //nolint:staticcheck // bufconn helper
		grpc.WithContextDialer(func(_ context.Context, _ string) (net.Conn, error) {
			return lis.Dial()
		}),
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	)
	require.NoError(h.t, err, "bufconn dial")

	h.GRPC = srv
	h.GRPCConn = conn
	h.FilesStub = stub
	h.ETClient = entitytypev1.NewEntityTypeServiceClient(conn)
	h.RTClient = relationshiptypev1.NewRelationshipTypeServiceClient(conn)
	h.CorpusClient = corpusv1.NewCorpusServiceClient(conn)
	h.DocClient = documentv1.NewDocumentServiceClient(conn)
	h.EntityClient = entityv1.NewEntityServiceClient(conn)
	h.EdgeClient = edgev1.NewEdgeServiceClient(conn)
}

// ----------------------------------------------------------------------
// Postgres seeding helpers
// ----------------------------------------------------------------------

// SeedCorpus inserts a document_collections row and returns its id.
func (h *TestHarness) SeedCorpus(ctx context.Context, name, visibility, collectionName string, ownerUserID *int64) int64 {
	h.t.Helper()
	var id int64
	err := h.pgPool.QueryRow(ctx, `
		INSERT INTO document_collections
		    (organization_id, name, description, visibility, user_id, vector_collection_name)
		VALUES ($1, $2, '', $3, $4, $5) RETURNING id
	`, h.Cfg.LegacyOrgID, name, visibility, ownerUserID, collectionName).Scan(&id)
	require.NoError(h.t, err)
	return id
}

// SeedDocument inserts a documents row and returns its id. content is
// also written to the LegacyDocs filesystem mock at filePath so Phase
// 4's filesystem reader can stream it.
func (h *TestHarness) SeedDocument(
	ctx context.Context,
	collectionID int64,
	filePath, filename, fileType string,
	uploadedBy *int64,
	content []byte,
) int64 {
	h.t.Helper()
	size := int64(len(content))
	var id int64
	err := h.pgPool.QueryRow(ctx, `
		INSERT INTO documents
		    (organization_id, collection_id, file_path, filename, title, file_type, file_size, uploaded_by)
		VALUES ($1, $2, $3, $4, $4, $5, $6, $7) RETURNING id
	`, h.Cfg.LegacyOrgID, collectionID, filePath, filename, fileType, size, uploadedBy).Scan(&id)
	require.NoError(h.t, err)

	// Also drop the bytes into the filesystem mock so Phase 4's
	// FS.Open finds them.
	h.LegacyDocs.Files[filePath] = content
	return id
}

// SeedChunk inserts a document_chunks row and returns its id. chromaID
// is the legacy Qdrant point id; pass empty string for chunks without
// embeddings (Phase 6 will skip them).
func (h *TestHarness) SeedChunk(
	ctx context.Context,
	docID int64,
	chunkIndex int32,
	content, chromaID, embeddingModel string,
	startChar, endChar *int32,
) int64 {
	h.t.Helper()
	var id int64
	err := h.pgPool.QueryRow(ctx, `
		INSERT INTO document_chunks
		    (document_id, chunk_index, content, start_char, end_char,
		     chroma_id, embedding_model, embedding_dimension)
		VALUES ($1, $2, $3, $4, $5, NULLIF($6, ''), NULLIF($7, ''), $8) RETURNING id
	`, docID, chunkIndex, content, startChar, endChar, chromaID, embeddingModel, h.Cfg.VectorDim).Scan(&id)
	require.NoError(h.t, err)
	return id
}

// ----------------------------------------------------------------------
// In-process gRPC stub
// ----------------------------------------------------------------------

// FilesStub holds the in-memory state for every stub service. It
// is goroutine-safe for the per-RPC operations the migrator performs;
// pipeline tests are single-goroutine so we don't need finer locking
// than the maps' map-write-during-RPC semantics.
type FilesStub struct {
	// EntityType state — Bootstrap registers each item; Get returns it.
	EntityTypes map[string]*entitytypev1.EntityType // new uuid → row

	// RelationshipType state.
	RelationshipTypes map[string]*relationshiptypev1.RelationshipType

	// Corpus state.
	Corpora map[string]*corpusv1.Corpus // new uuid → row

	// Document state — keyed by new doc UUID. Maps below split for
	// chunks + embeddings.
	Documents        map[string]*documentv1.Document
	Chunks           map[string]*documentv1.Chunk        // new chunk uuid → row
	ChunksByDoc      map[string][]string                  // new doc uuid → []new chunk uuid
	Embeddings       map[string][]float32                 // legacy chunk_id → vector (so we can assert pristine copy)

	// Entity / Edge state.
	Entities map[string]*entityv1.Entity
	Edges    map[string]*edgev1.Edge

	// Provenance counts. Tests use these to assert "0 inserted" for
	// the deferred-provenance gap path.
	EntityProvenanceLinks []*entityv1.MigrateProvenanceRequest_Link
	EdgeProvenanceLinks   []*edgev1.MigrateProvenanceRequest_Link

	// Per-RPC call counters — operators (and tests) want to confirm
	// a re-run actually re-issued the RPC rather than short-circuiting
	// on sidecar.
	BootstrapEntityTypesCalls       int
	BootstrapRelationshipTypesCalls int
	MigrateCorpusCalls              int
	MigrateUploadCalls              int
	MigrateChunksCalls              int
	MigrateChunkEmbeddingsCalls     int
	MigrateEntityCalls              int
	MigrateEdgeCalls                int
	MigrateEntityProvenanceCalls    int
	MigrateEdgeProvenanceCalls      int
}

func newFilesStub() *FilesStub {
	return &FilesStub{
		EntityTypes:       map[string]*entitytypev1.EntityType{},
		RelationshipTypes: map[string]*relationshiptypev1.RelationshipType{},
		Corpora:           map[string]*corpusv1.Corpus{},
		Documents:         map[string]*documentv1.Document{},
		Chunks:            map[string]*documentv1.Chunk{},
		ChunksByDoc:       map[string][]string{},
		Embeddings:        map[string][]float32{},
		Entities:          map[string]*entityv1.Entity{},
		Edges:             map[string]*edgev1.Edge{},
	}
}

// deterministicUUID returns a stable UUIDv5 derived from the legacy
// id. Reusing the same legacy id always yields the same UUID, so the
// stub's `already_migrated` semantics work without an explicit dedup
// table — we just check whether the EntityTypes map already contains
// the key.
func deterministicUUID(legacyID string) string {
	return uuid.NewSHA1(uuid.NameSpaceURL, []byte(legacyID)).String()
}

// registerFilesStub registers all stub services on the gRPC
// server. Keeping this as a free function (rather than a method on
// FilesStub) lets us register multiple servers against the same
// stub if a future test wants two parallel migrator runs.
func registerFilesStub(srv *grpc.Server, k *FilesStub) {
	entitytypev1.RegisterEntityTypeServiceServer(srv, &entityTypeStub{k: k})
	relationshiptypev1.RegisterRelationshipTypeServiceServer(srv, &relationshipTypeStub{k: k})
	corpusv1.RegisterCorpusServiceServer(srv, &corpusStub{k: k})
	documentv1.RegisterDocumentServiceServer(srv, &documentStub{k: k})
	entityv1.RegisterEntityServiceServer(srv, &entityStub{k: k})
	edgev1.RegisterEdgeServiceServer(srv, &edgeStub{k: k})
}

// ---- EntityTypeService ----

type entityTypeStub struct {
	entitytypev1.UnimplementedEntityTypeServiceServer
	k *FilesStub
}

func (s *entityTypeStub) Bootstrap(_ context.Context, req *entitytypev1.BootstrapRequest) (*entitytypev1.BootstrapResponse, error) {
	s.k.BootstrapEntityTypesCalls++
	idMap := make(map[string]string, len(req.GetItems()))
	for _, it := range req.GetItems() {
		legacyID := it.GetLegacyId().GetValue()
		newID := deterministicUUID(legacyID)
		if _, ok := s.k.EntityTypes[newID]; !ok {
			s.k.EntityTypes[newID] = &entitytypev1.EntityType{
				Id:          newID,
				Name:        it.GetName(),
				Description: it.GetDescription(),
				Color:       it.GetColor(),
				Icon:        it.GetIcon(),
				LegacyId:    &commonv1.LegacyID{Value: legacyID},
				CreatedAt:   timestamppb.Now(),
			}
		}
		idMap[legacyID] = newID
	}
	return &entitytypev1.BootstrapResponse{IdByLegacyId: idMap}, nil
}

func (s *entityTypeStub) Get(_ context.Context, req *entitytypev1.GetRequest) (*entitytypev1.GetResponse, error) {
	row, ok := s.k.EntityTypes[req.GetEntityTypeId()]
	if !ok {
		return nil, fmt.Errorf("entity_type not found: %s", req.GetEntityTypeId())
	}
	return &entitytypev1.GetResponse{EntityType: row}, nil
}

