func (s *corpusStub) MigrateCorpus(_ context.Context, req *corpusv1.MigrateCorpusRequest) (*corpusv1.MigrateCorpusResponse, error) {
	s.k.MigrateCorpusCalls++
	newID := deterministicUUID(req.GetLegacyId())
	if _, ok := s.k.Corpora[newID]; ok {
		return &corpusv1.MigrateCorpusResponse{Id: newID, AlreadyMigrated: true}, nil
	}
	s.k.Corpora[newID] = &corpusv1.Corpus{
		Id:          newID,
		Name:        req.GetName(),
		Description: req.GetDescription(),
		Visibility:  req.GetVisibility(),
		LegacyId:    &commonv1.LegacyID{Value: req.GetLegacyId()},
		CreatedAt:   req.GetCreatedAt(),
	}
	return &corpusv1.MigrateCorpusResponse{Id: newID, AlreadyMigrated: false}, nil
}

func (s *corpusStub) Get(_ context.Context, req *corpusv1.GetRequest) (*corpusv1.GetResponse, error) {
	row, ok := s.k.Corpora[req.GetCorpusId()]
