// ---- DocumentService ----

type documentStub struct {
	documentv1.UnimplementedDocumentServiceServer
	k *FilesStub
}

func (s *documentStub) MigrateUpload(_ context.Context, req *documentv1.MigrateUploadRequest) (*documentv1.MigrateUploadResponse, error) {
	s.k.MigrateUploadCalls++
	legacyID := req.GetLegacyId().GetValue()
	newID := deterministicUUID(legacyID)
	if existing, ok := s.k.Documents[newID]; ok {
		return &documentv1.MigrateUploadResponse{Document: existing, AlreadyMigrated: true}, nil
	}
	doc := &documentv1.Document{
		Id:          newID,
		CorpusId:    req.GetCorpusId(),
		Filename:    req.GetFilename(),
		MimeType:    req.GetMimeType(),
		SizeBytes:   req.GetSizeBytes(),
		MinioObject: req.GetMinioObject(),
		UploadedBy:  req.GetUploadedBy(),
		LegacyId:    &commonv1.LegacyID{Value: legacyID},
		UploadedAt:  req.GetUploadedAt(),
	}
	s.k.Documents[newID] = doc
	return &documentv1.MigrateUploadResponse{Document: doc, AlreadyMigrated: false}, nil
}

func (s *documentStub) MigrateChunks(_ context.Context, req *documentv1.MigrateChunksRequest) (*documentv1.MigrateChunksResponse, error) {
	s.k.MigrateChunksCalls++
	out := &documentv1.MigrateChunksResponse{}
	docID := req.GetDocumentId()
	for _, row := range req.GetChunks() {
		legacyID := row.GetLegacyId().GetValue()
		newID := deterministicUUID(legacyID)
		if _, ok := s.k.Chunks[newID]; ok {
			out.Chunks = append(out.Chunks, s.k.Chunks[newID])
			continue
		}
		c := &documentv1.Chunk{
			Id:         newID,
			DocumentId: docID,
			ChunkIndex: row.GetChunkIndex(),
			Text:       row.GetText(),
			LegacyId:   &commonv1.LegacyID{Value: legacyID},
		}
		if row.StartChar != nil {
			v := row.GetStartChar()
			c.StartChar = &v
		}
		if row.EndChar != nil {
			v := row.GetEndChar()
			c.EndChar = &v
		}
		s.k.Chunks[newID] = c
		s.k.ChunksByDoc[docID] = append(s.k.ChunksByDoc[docID], newID)
		out.Chunks = append(out.Chunks, c)
	}
	return out, nil
}

func (s *documentStub) MigrateChunkEmbeddings(_ context.Context, req *documentv1.MigrateChunkEmbeddingsRequest) (*documentv1.MigrateChunkEmbeddingsResponse, error) {
	s.k.MigrateChunkEmbeddingsCalls++
	written := int32(0)
	for _, e := range req.GetEmbeddings() {
		legacyID := e.GetChunkLegacyId().GetValue()
		s.k.Embeddings[legacyID] = append([]float32(nil), e.GetVector()...)
		written++
	}
	return &documentv1.MigrateChunkEmbeddingsResponse{WrittenCount: written}, nil
}

func (s *documentStub) Get(_ context.Context, req *documentv1.GetRequest) (*documentv1.GetResponse, error) {
	row, ok := s.k.Documents[req.GetDocumentId()]
	if !ok {
