// Package integration contains migrator-files integration tests against
// real testcontainers — no mocks, no in-memory shims.
//
// Helper containers provided:
//
//   - StartLegacyPostgres: a postgres:16.4-alpine container with the
//     subset of the legacy OmniCore schema that migrator-files
//     reads (entity_types, relationship_types, document_collections,
//     documents, document_chunks, etc.). Schema is expanded in Tasks
//     7-15 as each phase's reader is implemented.
//
//   - StartNATS: a nats:2.10-alpine container with JetStream enabled.
//     Used to verify the JetStream KV cursor adapter round-trips
//     correctly.
//
// Tests use testing.Short() to skip — `make migrator-files-test` skips
// these (no Docker required); `make migrator-files-test-int` runs them.
package integration

import (
	"context"
	"testing"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/stretchr/testify/require"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/modules/postgres"
	"github.com/testcontainers/testcontainers-go/wait"
)

// LegacySchemaDDL is the minimal subset of the legacy OmniCore schema
// migrator-files reads. Expanded in Tasks 7-15 as each phase's
// reader lands. Pinned here as a constant so a query-plan reviewer can
// see exactly what shape the SQL in internal/legacy/ runs against.
const LegacySchemaDDL = `
-- Phase 1: entity types taxonomy
CREATE TABLE entity_types (
    id          BIGSERIAL PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Phase 2: relationship types taxonomy
CREATE TABLE relationship_types (
    id          BIGSERIAL PRIMARY KEY,
    name        TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
`

// StartLegacyPostgres boots a postgres container, applies LegacySchemaDDL,
// and returns a connected pgx pool plus the DSN (so tests can pass
// the DSN to legacy.NewReader directly).
func StartLegacyPostgres(t *testing.T) (pool *pgxpool.Pool, dsn string, cleanup func()) {
	t.Helper()
	ctx := context.Background()

	pgC, err := postgres.Run(ctx,
		"postgres:16.4-alpine",
		postgres.WithDatabase("legacy_test"),
		postgres.WithUsername("postgres"),
		postgres.WithPassword("test"),
		testcontainers.WithWaitStrategy(
			wait.ForLog("database system is ready to accept connections").
				WithOccurrence(2).
				WithStartupTimeout(60*time.Second),
		),
	)
	require.NoError(t, err)

	dsn, err = pgC.ConnectionString(ctx, "sslmode=disable")
	require.NoError(t, err)

	pool, err = pgxpool.New(ctx, dsn)
	require.NoError(t, err)

	_, err = pool.Exec(ctx, LegacySchemaDDL)
	require.NoError(t, err)

	cleanup = func() {
		pool.Close()
		_ = pgC.Terminate(ctx)
	}
	return pool, dsn, cleanup
}

// StartNATS boots a nats:2.10-alpine container with JetStream
// enabled and returns the connection URL.
//
// Mirrors the pattern already in
// platform/libs/go/eventbus/publisher_test.go — generic container,
// "Server is ready" wait strategy.
func StartNATS(t *testing.T) (url string, cleanup func()) {
	t.Helper()
	ctx := context.Background()
	req := testcontainers.ContainerRequest{
		Image:        "nats:2.10-alpine",
		ExposedPorts: []string{"4222/tcp"},
		Cmd:          []string{"--jetstream", "-m", "8222"},
		// macOS Docker Desktop can log "Server is ready" before host
		// port forwarding is up. Wait for both.
		WaitingFor: wait.ForAll(
			wait.ForLog("Server is ready").WithStartupTimeout(30*time.Second),
			wait.ForListeningPort("4222/tcp").WithStartupTimeout(30*time.Second),
		),
	}
	c, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: req,
		Started:          true,
	})
	require.NoError(t, err)

	host, err := c.Host(ctx)
	require.NoError(t, err)
	port, err := c.MappedPort(ctx, "4222/tcp")
	require.NoError(t, err)

	url = "nats://" + host + ":" + port.Port()
	cleanup = func() { _ = c.Terminate(ctx) }
	return url, cleanup
}


